#include "ksPanelPollCalls.h"
#include "ksControllerBoundary.h"
#include <stdexcept>
namespace ks{namespace{PanelPollPartialTest partialTest=nullptr;using S=PanelPollTask::Stage;struct Point{unsigned location,length;};Point point(S s){switch(s){case S::DispatchStatus:return{0x8ea,2};case S::AwaitStatus:case S::TestReady:return{0x8ec,2};case S::AdmitReady:return{0x8ee,2};case S::WaitFirst:return{0x8f0,2};case S::WaitSecond:return{0x8f2,2};case S::WaitThird:return{0x8f4,2};case S::WaitFourth:return{0x8f6,2};case S::DispatchFinal:return{0x8f8,2};case S::AwaitFinal:case S::Finish:return{0x8fa,2};default:throw std::runtime_error("Invalid panel poll stage");}}}
bool PanelPollCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token==h.getSP()){selected=&c;break;}if(pc==0x8ea&&!selected){for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Panel poll capacity");selected->emplace(h.getSP());++started;}if(!selected||point((**selected).task.stage()).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto&v=h.regs;if(t.awaiting())t.resumeChild(uint8_t(v[6].rl));auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(stage).length);auto cost=t.nextClocks();t.advanceBefore(cost);switch(stage){case S::TestReady:f.move(v[6].rl,t.reply());break;case S::DispatchStatus:case S::DispatchFinal:f.call(0x87e);h.pc=h.makepc(f.next);break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::DispatchStatus&&stage!=S::DispatchFinal&&stage!=S::Finish)h.pc=h.makepc(point(t.stage()).location);if(h.cycles-before!=cost)throw std::runtime_error("Panel poll clocks differ");return true;}}

namespace ks{void setPanelPollPartialForTests(PanelPollPartialTest fn){partialTest=fn;}}
